import json,re
d=json.load(open('docs/coop/artifacts/delivery.v4.json'))
print(list(d.keys()))
def find(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if 'apab' in k.lower() or 'capab' in k.lower() or 'CAP-MANIFEST' in str(k): print('KEY',p+'.'+k)
            find(v,p+'.'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): find(v,p+'[%d]'%i)
    elif isinstance(o,str):
        if 'CAP-MANIFEST-ID-V1' in o: print('VAL',p,'=',o[:200])
find(d)
EOF

