cd /tmp/opensip-design-corrections/consumer-b.v2/subject && /tmp/opensip-architecture-review-env/bin/python -I -B - <<'EOF'
import json
d=json.load(open('docs/coop/design-corrections/foundation/identity-schemas.v2.json'))
defs=d['$defs']
def sig(name):
    s=defs[name]
    out={'req':s.get('required'),'ap':s.get('additionalProperties')}
    props={}
    for k,v in (s.get('properties') or {}).items():
        e={}
        for kk in ('type','const','enum','pattern','minimum','maximum','x-opensip-digest','x-opensip-order','$ref','maxLength','minItems','maxItems'):
            if kk in v: e[kk]=v[kk]
        if v.get('type')=='array':
            it=v.get('items',{})
            e['items']={kk:it[kk] for kk in ('type','$ref','pattern','x-opensip-order') if kk in it}
            if 'x-opensip-order' in v: e['x-opensip-order']=v['x-opensip-order']
        props[k]=e
    out['props']=props
    return out
for n in ['snapshot','plan','run','view','fact','coverage','subject-scope','closure','Ref']:
    print('===',n)
    print(json.dumps(sig(n),indent=1))
EOF

